"""Reproduce pins, generated bytes, key outcomes and exact hashes; leave no files."""

import json
from pathlib import Path
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
sys.path.insert(1, str(ROOT))

from harness.bindings import candidate
from harness.common import CORPUS, FREEZE_SHA256, canonical, digest, sha
from harness.report import expected_rows, row_identity
from prepare import artifacts, bindings, declaration


def require(condition, message):
    if not condition:
        raise ValueError(message)


def frozen_corpus():
    raw = (CORPUS / "FREEZE.json").read_bytes()
    require(sha(raw) == FREEZE_SHA256, "frozen corpus identity changed")
    manifest = json.loads(raw)
    require(set(manifest["files"]) == {p.name for p in CORPUS.iterdir() if p.is_file()}, "corpus file set changed")
    for name, expected in manifest["files"].items():
        if name != "FREEZE.json":
            require(sha((CORPUS / name).read_bytes()) == expected, "corpus pin changed: " + name)
    normalized = json.loads(raw)
    normalized["files"]["FREEZE.json"] = None
    require(digest(normalized) == manifest["files"]["FREEZE.json"], "corpus self pin changed")
    require(digest({k: v for k, v in manifest["files"].items() if k != "FREEZE.json"}) == manifest["content_sha256"], "corpus content pin changed")


def projection(rows):
    result = {}
    for row in rows:
        key = "/".join(str(row[k]) for k in ("form", "variant", "case_id", "run_id", "host_variant"))
        record = row["record"]
        value = {"classification": row["classification"],
                 "run_key": record["exact"]["input_identities"]["run_key"] if record else None,
                 "sha256": record["sha256"] if record else None}
        if key in result:
            require(result[key] == value, "nonreproducible observation: " + key)
        result[key] = value
    return result


def snapshot():
    return {p.relative_to(HERE).as_posix(): sha(p.read_bytes()) for p in HERE.rglob("*")
            if p.is_file() and "build" not in p.relative_to(HERE).parts}


def main():
    build = HERE / "build"
    require(not build.exists(), "build must be absent before acceptance")
    before = snapshot()
    try:
        frozen_corpus()
        manifest, pins = candidate(HERE)
        versions = pins["execution_contract"]["versions"]
        require(sys.version.split()[0] == versions["Python"], "Python version pin changed")
        require(subprocess.check_output(["node", "--version"], cwd=HERE).decode("ascii").strip() == versions["Node"], "Node version pin changed")
        rendered, spans = artifacts()
        for name, data in rendered.items():
            require(data == (HERE / name).read_bytes(), "rendered bytes changed: " + name)
        require(manifest == declaration(), "candidate declaration changed")
        require(pins == bindings(rendered, spans, manifest), "binding recipe changed")
        evidence = json.loads((HERE / "evidence.json").read_bytes())
        for name, expected in evidence["files"].items():
            require(sha((HERE / name).read_bytes()) == expected, "retained evidence changed: " + name)
        build.mkdir()
        subprocess.run([sys.executable, "-B", str(HERE / "probe.py")], cwd=ROOT, check=True, timeout=90)
        subprocess.run([sys.executable, "-B", str(ROOT / "run_matrix.py"),
                        "--candidate", "candidates/rt3-wasm", "--out", "candidates/rt3-wasm/build/check",
                        "--runs", "1", "--leg", "Windows"], cwd=ROOT, check=True, timeout=840)
        fresh = json.loads((build / "check/summary.json").read_bytes())
        stored = json.loads((HERE / "summary.json").read_bytes())
        rows = [json.loads(line) for line in (build / "check/results.jsonl").read_bytes().splitlines()]
        require({row_identity(row) for row in rows} == expected_rows(manifest, 1, ["Windows"]), "missing outcome")
        require(projection(rows) == json.loads((HERE / "outcomes.json").read_bytes()), "key, payload or outcome changed")
        for actual, expected in zip(fresh["cells"], stored["cells"], strict=True):
            require(set(actual["hashes"]) == set(expected["hashes"]), "missing exact payload")
            for key, values in actual["hashes"].items():
                require({(v["run_key"], v["sha256"]) for v in values} ==
                        {(v["run_key"], v["sha256"]) for v in expected["hashes"][key]}, "summary hash changed: " + key)
        print("PASS: corpus and source pins, lowering, 522 outcomes, exact hashes and key identities reproduced.")
    finally:
        # Verify the absolute deletion target remains the candidate-owned build.
        require(build.resolve().parent == HERE.resolve() and build.name == "build", "unsafe cleanup target")
        if build.exists():
            shutil.rmtree(build)
        require(snapshot() == before, "acceptance changed retained candidate bytes")
        require(not build.exists(), "acceptance left build products")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
